/// Send one meta_* command to the sidecar and return its `meta_result`
/// reply, correlated by the generated `id` on the shared agent-output bus
/// (same subscribe-before-send discipline as `/runtime/chat`).
/// Sprint 1.6 — Memory Resume. Same subscribe-before-send discipline as
/// `meta_roundtrip`; differs only in the inbound `type` ("resume_get") and
/// the matched outbound reply type ("resume_get_result"). The Tauri desktop
/// command `get_last_task` inlines the same pattern (see
/// `src-tauri/src/memory_resume.rs`) so the two call paths can't drift.
async fn runtime_resume(State(state): State<ApiState>) -> Response {
    let tx = { state.runtime.feral_agent_tx.lock().as_ref().cloned() };
    let Some(tx) = tx else {
        // Sidecar isn't running — first launch with no memory, or gateway
        // running headless without the agent. Empty payload is the right
        // safe default so the TUI / curl callers can render "fresh start".
        return Json(json!({
            "task": null,
            "workspace_id": null,
            "workspace_name": null,
            "last_active_at": null,
        }))
        .into_response();
    };
    let msg_id = uuid::Uuid::new_v4().to_string();
    let mut rx = state.runtime.events_tx.subscribe();
    if tx
        .send(json!({ "type": "resume_get", "id": msg_id }).to_string())
        .await
        .is_err()
    {
        return Json(json!({
            "task": null,
            "workspace_id": null,
            "workspace_name": null,
            "last_active_at": null,
        }))
        .into_response();
    }
    let deadline = std::time::Duration::from_millis(1500);
    loop {
        match tokio::time::timeout(deadline, rx.recv()).await {
            Ok(Ok(ev)) => {
                if ev.event != "feral://agent-output" {
                    continue;
                }
                let Some(line) = ev.payload.get("data").and_then(|s| s.as_str()) else {
                    continue;
                };
                let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
                if v.get("type").and_then(|t| t.as_str()) == Some("resume_get_result")
                    && v.get("id").and_then(|i| i.as_str()) == Some(msg_id.as_str())
                {
                    return Json(v).into_response();
                }
            }
            Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
            Ok(Err(broadcast::error::RecvError::Closed)) => {
                return Json(json!({
                    "task": null,
                    "workspace_id": null,
                    "workspace_name": null,
                    "last_active_at": null,
                }))
                .into_response();
            }
            Err(_) => {
                return Json(json!({
                    "task": null,
                    "workspace_id": null,
                    "workspace_name": null,
                    "last_active_at": null,
                }))
                .into_response();
            }
        }
    }
}

async fn meta_roundtrip(State(state): State<ApiState>, op: &'static str) -> Response {
    let tx = { state.runtime.feral_agent_tx.lock().as_ref().cloned() };
    let Some(tx) = tx else {
        return (StatusCode::SERVICE_UNAVAILABLE, "feral-agent sidecar is not running")
            .into_response();
    };
    let msg_id = uuid::Uuid::new_v4().to_string();
    let mut rx = state.runtime.events_tx.subscribe();
    if tx.send(json!({ "type": op, "id": msg_id }).to_string()).await.is_err() {
        return (StatusCode::SERVICE_UNAVAILABLE, "sidecar stopped accepting messages")
            .into_response();
    }
    let deadline = std::time::Duration::from_secs(10);
    loop {
        match tokio::time::timeout(deadline, rx.recv()).await {
            Ok(Ok(ev)) => {
                if ev.event != "feral://agent-output" {
                    continue;
                }
                let Some(line) = ev.payload.get("data").and_then(|s| s.as_str()) else { continue };
                let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
                if v.get("type").and_then(|t| t.as_str()) == Some("meta_result")
                    && v.get("id").and_then(|i| i.as_str()) == Some(msg_id.as_str())
                {
                    return Json(v).into_response();
                }
            }
            Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
            Ok(Err(broadcast::error::RecvError::Closed)) => {
                return (StatusCode::SERVICE_UNAVAILABLE, "runtime event bus closed").into_response()
            }
            Err(_) => {
                return (StatusCode::GATEWAY_TIMEOUT, "timed out waiting for meta_result")
                    .into_response()
            }
        }
    }
}

// ── Slice A5 (L5 Governance API — spec §12) ─────────────────────────────
//
// Mirrors `meta_roundtrip` line-by-line: subscribe-before-send, wait on the
// runtime event bus for one `governance_result` correlated by `id`. Differs
// in three ways:
//   1. Filters on `type == "governance_result"` (the new reply union in
//      `FeralAgent/src/types.ts`) instead of `"meta_result"`.
//   2. Accepts an optional JSON body whose top-level fields are flattened
//      onto the outbound message alongside `type` + `id`. The sidecar's
//      handler (`FeralAgent/src/index.ts`) reads these fields directly —
//      no per-op message shape was added.
//   3. Per spec §12 the routes are tagged read/evolve/govern in comments
//      (no enforcement in v1; a future RBAC layer will branch on the tag).

/// Forward a governance op to the sidecar and return its `governance_result`.
/// Optional `body` fields are flattened onto the outbound message envelope.
async fn governance_roundtrip(
    State(state): State<ApiState>,
    op: &'static str,
    body: Option<Json<Value>>,
) -> Response {
    let tx = { state.runtime.feral_agent_tx.lock().as_ref().cloned() };
    let Some(tx) = tx else {
        return (StatusCode::SERVICE_UNAVAILABLE, "feral-agent sidecar is not running")
            .into_response();
    };
    let msg_id = uuid::Uuid::new_v4().to_string();
    let mut rx = state.runtime.events_tx.subscribe();

    // Build the outbound envelope. Body fields overwrite defaults; missing
    // body → minimal `{ type, id }` envelope (the sidecar's handler defaults
    // missing fields to sensible empties — see brief §1 op-mapping table).
    let mut payload = json!({ "type": op, "id": msg_id });
    if let Some(Json(Value::Object(map))) = body {
        for (k, v) in map {
            payload[k] = v;
        }
    }
    if tx.send(payload.to_string()).await.is_err() {
        return (StatusCode::SERVICE_UNAVAILABLE, "sidecar stopped accepting messages")
            .into_response();
    }
    let deadline = std::time::Duration::from_secs(10);
    loop {
        match tokio::time::timeout(deadline, rx.recv()).await {
            Ok(Ok(ev)) => {
                if ev.event != "feral://agent-output" {
                    continue;
                }
                let Some(line) = ev.payload.get("data").and_then(|s| s.as_str()) else {
                    continue;
                };
                let Ok(v) = serde_json::from_str::<Value>(line) else {
                    continue;
                };
                if v.get("type").and_then(|t| t.as_str()) == Some("governance_result")
                    && v.get("id").and_then(|i| i.as_str()) == Some(msg_id.as_str())
                {
                    return Json(v).into_response();
                }
            }
            Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
            Ok(Err(broadcast::error::RecvError::Closed)) => {
                return (StatusCode::SERVICE_UNAVAILABLE, "runtime event bus closed")
                    .into_response();
            }
            Err(_) => {
                return (StatusCode::GATEWAY_TIMEOUT, "timed out waiting for governance_result")
                    .into_response();
            }
        }
    }
}

